import{_ as l,r as o,o as i,c as r,b as a,d as s,a as e,w as p,e as c}from"./app-84ed3530.js";const u={};function d(k,n){const t=o("RouterLink");return i(),r("div",null,[n[13]||(n[13]=a("h1",{id:"kubernetes-入门到上手",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#kubernetes-入门到上手","aria-hidden":"true"},"#"),s(" Kubernetes 入门到上手")],-1)),a("blockquote",null,[a("p",null,[n[1]||(n[1]=s("容器编排的事实标准。本文从「为什么需要」讲到核心对象、部署与扩缩容，定位是",-1)),n[2]||(n[2]=a("strong",null,"全栈工程师的够用深度",-1)),n[3]||(n[3]=s("：看得懂部署清单、能排障、知道边界在哪。前置知识：",-1)),e(t,{to:"/blogs/backend/docker.html"},{default:p(()=>[...n[0]||(n[0]=[s("Docker",-1)])]),_:1}),n[4]||(n[4]=s("。",-1))])]),n[14]||(n[14]=c(`<hr><h2 id="_1-为什么需要-k8s" tabindex="-1"><a class="header-anchor" href="#_1-为什么需要-k8s" aria-hidden="true">#</a> 1. 为什么需要 K8s</h2><p>Docker/Compose 解决单机；多机时问题全来了：容器挂了谁重启？流量怎么分到健康实例？发版怎么不停机？机器满了怎么扩？K8s 用声明式 API + 控制循环回答这一切：</p><ul><li><strong>声明式</strong>：你描述「期望状态」（跑 3 个副本、用这个镜像），K8s 持续比对现实并自动收敛</li><li><strong>自愈</strong>：容器挂了自动重启，节点宕机自动迁移</li><li><strong>水平扩缩容、滚动更新、服务发现、配置管理</strong>：都是内置能力</li></ul><hr><h2 id="_2-架构一图" tabindex="-1"><a class="header-anchor" href="#_2-架构一图" aria-hidden="true">#</a> 2. 架构一图</h2><div class="language-mermaid line-numbers-mode" data-ext="mermaid"><pre class="language-mermaid"><code><span class="token keyword">flowchart</span> TB
  <span class="token keyword">subgraph</span> CP<span class="token text string">[&quot;控制平面 Control Plane&quot;]</span>
    API<span class="token text string">[&quot;API Server&lt;br/&gt;唯一入口&quot;]</span> <span class="token arrow operator">---</span> ETCD<span class="token text string">[&quot;etcd&lt;br/&gt;存储所有状态&quot;]</span>
    SCHED<span class="token text string">[&quot;Scheduler&lt;br/&gt;决定 Pod 放哪台机器&quot;]</span>
    CM<span class="token text string">[&quot;Controller Manager&lt;br/&gt;维持期望状态&quot;]</span>
  <span class="token keyword">end</span>
  <span class="token keyword">subgraph</span> N1<span class="token text string">[&quot;Node（工作节点 × N）&quot;]</span>
    K<span class="token text string">[&quot;kubelet&lt;br/&gt;管理本机容器&quot;]</span> <span class="token arrow operator">--&gt;</span> CR<span class="token text string">[&quot;containerd&lt;br/&gt;真正跑容器&quot;]</span>
    KP<span class="token text string">[&quot;kube-proxy&lt;br/&gt; Service 流量转发&quot;]</span>
    P1<span class="token text string">[&quot;Pod&quot;]</span> <span class="token arrow operator">---</span> P2<span class="token text string">[&quot;Pod&quot;]</span>
  <span class="token keyword">end</span>
  kubectl <span class="token arrow operator">--&gt;</span> API
  API <span class="token arrow operator">---</span> K
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>记忆点：<strong>所有操作都走 API Server，所有状态都存 etcd</strong>；kubelet 在每台工作节点上听命于 API Server。</p><hr><h2 id="_3-核心对象-掌握这-8-个就够日常" tabindex="-1"><a class="header-anchor" href="#_3-核心对象-掌握这-8-个就够日常" aria-hidden="true">#</a> 3. 核心对象（掌握这 8 个就够日常）</h2><table><thead><tr><th>对象</th><th>一句话</th><th>关键点</th></tr></thead><tbody><tr><td><strong>Pod</strong></td><td>最小调度单位，1~N 个共享网络/存储的容器</td><td>容器不是调度单位，Pod 才是；IP 每个 Pod 独立</td></tr><tr><td><strong>Deployment</strong></td><td>无状态应用的管家</td><td>声明副本数/镜像，负责滚动更新与回滚</td></tr><tr><td><strong>Service</strong></td><td>一组 Pod 的稳定访问入口（虚拟 IP）</td><td>通过 label 选择器绑定 Pod；Pod 换 IP 无影响</td></tr><tr><td><strong>Ingress</strong></td><td>七层入口：域名/路径 → Service</td><td>需搭配 Ingress Controller（nginx/traefik）实现</td></tr><tr><td><strong>ConfigMap</strong></td><td>配置与代码分离</td><td>以环境变量或文件挂载进容器</td></tr><tr><td><strong>Secret</strong></td><td>敏感配置</td><td>base64 编码（非加密！），生产配外部 KMS/Vault</td></tr><tr><td><strong>StatefulSet</strong></td><td>有状态应用</td><td>稳定主机名与顺序部署，数据库/中间件用</td></tr><tr><td><strong>PV / PVC</strong></td><td>存储的供给侧与申请侧</td><td>Pod 生命 ≠ 数据生命，持久数据必挂 PVC</td></tr></tbody></table><h3 id="一份最小可读的-deployment-service" tabindex="-1"><a class="header-anchor" href="#一份最小可读的-deployment-service" aria-hidden="true">#</a> 一份最小可读的 Deployment + Service</h3><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> apps/v1
<span class="token key atrule">kind</span><span class="token punctuation">:</span> Deployment
<span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> api
<span class="token key atrule">spec</span><span class="token punctuation">:</span>
  <span class="token key atrule">replicas</span><span class="token punctuation">:</span> <span class="token number">3</span>
  <span class="token key atrule">selector</span><span class="token punctuation">:</span>
    <span class="token key atrule">matchLabels</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">app</span><span class="token punctuation">:</span> api <span class="token punctuation">}</span>
  <span class="token key atrule">template</span><span class="token punctuation">:</span>
    <span class="token key atrule">metadata</span><span class="token punctuation">:</span>
      <span class="token key atrule">labels</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">app</span><span class="token punctuation">:</span> api <span class="token punctuation">}</span>        <span class="token comment"># Service 靠这个 label 找到 Pod</span>
    <span class="token key atrule">spec</span><span class="token punctuation">:</span>
      <span class="token key atrule">containers</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> api
          <span class="token key atrule">image</span><span class="token punctuation">:</span> registry.example.com/myapp/api<span class="token punctuation">:</span>1.4.2   <span class="token comment"># 固定 tag，别用 latest</span>
          <span class="token key atrule">ports</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token key atrule">containerPort</span><span class="token punctuation">:</span> <span class="token number">3000</span> <span class="token punctuation">}</span><span class="token punctuation">]</span>
          <span class="token key atrule">resources</span><span class="token punctuation">:</span>
            <span class="token key atrule">requests</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">cpu</span><span class="token punctuation">:</span> 100m<span class="token punctuation">,</span> <span class="token key atrule">memory</span><span class="token punctuation">:</span> 128Mi <span class="token punctuation">}</span>  <span class="token comment"># 调度依据</span>
            <span class="token key atrule">limits</span><span class="token punctuation">:</span>   <span class="token punctuation">{</span> <span class="token key atrule">cpu</span><span class="token punctuation">:</span> 500m<span class="token punctuation">,</span> <span class="token key atrule">memory</span><span class="token punctuation">:</span> 512Mi <span class="token punctuation">}</span>  <span class="token comment"># 硬上限（超限 OOMKill）</span>
          <span class="token key atrule">readinessProbe</span><span class="token punctuation">:</span>           <span class="token comment"># 就绪才接流量</span>
            <span class="token key atrule">httpGet</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">path</span><span class="token punctuation">:</span> /healthz<span class="token punctuation">,</span> <span class="token key atrule">port</span><span class="token punctuation">:</span> <span class="token number">3000</span> <span class="token punctuation">}</span>
          <span class="token key atrule">livenessProbe</span><span class="token punctuation">:</span>            <span class="token comment"># 不通就重启</span>
            <span class="token key atrule">httpGet</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">path</span><span class="token punctuation">:</span> /healthz<span class="token punctuation">,</span> <span class="token key atrule">port</span><span class="token punctuation">:</span> <span class="token number">3000</span> <span class="token punctuation">}</span>
          <span class="token key atrule">envFrom</span><span class="token punctuation">:</span>
            <span class="token punctuation">-</span> <span class="token key atrule">configMapRef</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> api<span class="token punctuation">-</span>config <span class="token punctuation">}</span>
<span class="token punctuation">---</span>
<span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> v1
<span class="token key atrule">kind</span><span class="token punctuation">:</span> Service
<span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> api
<span class="token key atrule">spec</span><span class="token punctuation">:</span>
  <span class="token key atrule">selector</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">app</span><span class="token punctuation">:</span> api <span class="token punctuation">}</span>
  <span class="token key atrule">ports</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token key atrule">port</span><span class="token punctuation">:</span> <span class="token number">80</span><span class="token punctuation">,</span> <span class="token key atrule">targetPort</span><span class="token punctuation">:</span> <span class="token number">3000</span> <span class="token punctuation">}</span><span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_4-发布-滚动更新与回滚" tabindex="-1"><a class="header-anchor" href="#_4-发布-滚动更新与回滚" aria-hidden="true">#</a> 4. 发布：滚动更新与回滚</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token builtin class-name">set</span> image deploy/api <span class="token assign-left variable">api</span><span class="token operator">=</span>myapp/api:1.5.0
kubectl rollout status deploy/api
kubectl rollout undo deploy/api          <span class="token comment"># 一键回滚</span>
kubectl rollout <span class="token function">history</span> deploy/api
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>滚动更新逻辑：按 <code>maxSurge</code>/<code>maxUnavailable</code> 先起新 Pod → readinessProbe 通过 → 杀旧 Pod，循环推进。<strong>readiness 探针就是不停机的关键</strong>：未就绪的 Pod 会被自动摘出 Service 后端。</p><hr><h2 id="_5-弹性伸缩" tabindex="-1"><a class="header-anchor" href="#_5-弹性伸缩" aria-hidden="true">#</a> 5. 弹性伸缩</h2><table><thead><tr><th>类型</th><th>对象</th><th>依据</th></tr></thead><tbody><tr><td>HPA（Horizontal）</td><td>Pod 副本数</td><td>CPU/内存利用率或自定义指标</td></tr><tr><td>VPA</td><td>Pod 资源规格</td><td>实际用量建议/调整（与 HPA 同用需谨慎）</td></tr><tr><td>Cluster Autoscaler</td><td>节点数</td><td>Pod 调度不下时加机器</td></tr></tbody></table><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl autoscale deploy api <span class="token parameter variable">--min</span><span class="token operator">=</span><span class="token number">3</span> <span class="token parameter variable">--max</span><span class="token operator">=</span><span class="token number">10</span> --cpu-percent<span class="token operator">=</span><span class="token number">70</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><hr><h2 id="_6-全栈工程师的「够用边界」" tabindex="-1"><a class="header-anchor" href="#_6-全栈工程师的「够用边界」" aria-hidden="true">#</a> 6. 全栈工程师的「够用边界」</h2><p><strong>必须会</strong>：</p><ul><li>写/看 Deployment + Service + Ingress + ConfigMap 清单</li><li><code>kubectl get/logs/describe/exec port-forward</code> 五连排障</li><li>理解探针、资源 requests/limits、滚动更新</li></ul><p><strong>常用命令</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pods <span class="token parameter variable">-o</span> wide / kubectl describe pod api-xxxx   <span class="token comment"># 事件与失败原因都在 describe 里</span>
kubectl logs <span class="token parameter variable">-f</span> api-xxxx <span class="token parameter variable">--previous</span>                        <span class="token comment"># 看上一次崩溃的日志</span>
kubectl <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> api-xxxx -- <span class="token function">sh</span>
kubectl port-forward svc/api <span class="token number">3000</span>:80                       <span class="token comment"># 本地调试</span>
kubectl <span class="token function">top</span> pods                                           <span class="token comment"># 资源用量（需 metrics-server）</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>知道即可</strong>（用到再学）：Helm（应用包管理，模板化清单）、Operator（有状态应用自动化）、CRD（自定义资源）、Service Mesh（Istio 流量治理）、GitOps（ArgoCD/Flux，清单进 git 自动同步）。</p><p><strong>排障心法</strong>：Pod 起不来先 <code>describe</code> 看 Events（镜像拉取失败/资源不足/探针失败三大件），再看 logs；<code>CrashLoopBackOff</code> 多半是应用自身启动即崩，<code>--previous</code> 看崩溃前日志。</p><hr><h2 id="_7-落地建议" tabindex="-1"><a class="header-anchor" href="#_7-落地建议" aria-hidden="true">#</a> 7. 落地建议</h2><ul><li><input type="checkbox" class="task-checkbox" disabled> 本地用 minikube / kind / docker desktop K8s 起个集群练手</li><li><input type="checkbox" class="task-checkbox" disabled> 把自己的服务容器化并写成 Deployment 部署上去，配齐三种探针</li><li><input type="checkbox" class="task-checkbox" disabled> 体验一次「杀掉 Pod → 自动重建」「改镜像 → 滚动更新 → undo 回滚」</li><li><input type="checkbox" class="task-checkbox" disabled> 生产用托管服务（ACK/EKS/GKE/TKE），别自己运维控制平面</li></ul>`,32)),a("blockquote",null,[a("p",null,[n[9]||(n[9]=s("延伸：",-1)),e(t,{to:"/blogs/backend/docker.html"},{default:p(()=>[...n[5]||(n[5]=[s("Docker",-1)])]),_:1}),n[10]||(n[10]=s(" · ",-1)),e(t,{to:"/blogs/backend/Nginx.html"},{default:p(()=>[...n[6]||(n[6]=[s("Nginx",-1)])]),_:1}),n[11]||(n[11]=s(" · ",-1)),e(t,{to:"/blogs/backend/mq.html"},{default:p(()=>[...n[7]||(n[7]=[s("消息队列",-1)])]),_:1}),n[12]||(n[12]=s(" · ",-1)),e(t,{to:"/blogs/backend/%E5%90%8E%E7%AB%AF%E6%9E%B6%E6%9E%84%E8%AE%BE%E8%AE%A1.html"},{default:p(()=>[...n[8]||(n[8]=[s("后端架构设计",-1)])]),_:1})])])])}const m=l(u,[["render",d],["__file","k8s.html.vue"]]);export{m as default};
